import React, { useState, useEffect, useRef, useMemo } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

const fmtMoney = (n) => {
  const v = Number(n || 0);
  return "$" + v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

function useModel() {
  const [model, setModel] = useState(appsmith.model || {});
  const lastRef = useRef("");
  useEffect(() => {
    const tick = () => {
      const m = appsmith.model || {};
      const s = JSON.stringify(m);
      if (s !== lastRef.current) { lastRef.current = s; setModel(m); }
    };
    tick();
    const id = setInterval(tick, 300);
    return () => clearInterval(id);
  }, []);
  return model;
}

function groupByMonth(rows) {
  const groups = [];
  const idx = {};
  (rows || []).forEach((r) => {
    const k = r.month_key;
    if (idx[k] === undefined) { idx[k] = groups.length; groups.push({ key: k, label: r.month_label, total: 0, rows: [] }); }
    const g = groups[idx[k]];
    g.rows.push(r);
    g.total += Number(r.total_amount_due || 0);
  });
  return groups;
}

function DownloadIcon() {
  return React.createElement("svg", { width: 16, height: 16, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 2, strokeLinecap: "round", strokeLinejoin: "round" },
    React.createElement("path", { d: "M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" }),
    React.createElement("polyline", { points: "7 10 12 15 17 10" }),
    React.createElement("line", { x1: 12, y1: 15, x2: 12, y2: 3 })
  );
}

function App() {
  const model = useModel();
  const rows = model.rows || [];
  const loading = !!model.loading;
  const done = !!model.done;
  const error = model.error || null;
  const groups = useMemo(() => groupByMonth(rows), [rows]);

  const [modalOpen, setModalOpen] = useState(false);
  const [modalDate, setModalDate] = useState(null);
  const [modalDisp, setModalDisp] = useState("");
  const [picked, setPicked] = useState({});
  const [center, setCenter] = useState(null);

  const sentinelRef = useRef(null);
  const inFlight = useRef(false);

  useEffect(() => { if (!loading) inFlight.current = false; }, [loading]);

  const requestMore = () => {
    if (inFlight.current || loading || done || error) return;
    inFlight.current = true;
    appsmith.triggerEvent("onLoadMore");
  };

  useEffect(() => {
    if (rows.length === 0 && !done && !loading && !error) requestMore();
  }, [rows.length, done, loading, error]);

  useEffect(() => {
    const el = sentinelRef.current;
    if (!el) return;
    const obs = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) requestMore();
    }, { root: null, rootMargin: "250px", threshold: 0 });
    obs.observe(el);
    return () => obs.disconnect();
  }, [done, loading, error, rows.length]);

    const openBatch = (r, e) => {
    let c = null;
    try {
      const vw = window.innerWidth || 0;
      const vh = window.innerHeight || 0;
      let anchorY = vh / 2;
      if (e && e.currentTarget && e.currentTarget.getBoundingClientRect) {
        const rect = e.currentTarget.getBoundingClientRect();
        anchorY = rect.top + rect.height / 2;
      }
      const maxH = Math.min(Math.max(vh - 40, 200), 560);
      const half = maxH / 2 + 20;
      const y = Math.max(half, Math.min(vh - half, anchorY));
      c = { x: vw / 2, y: y, maxH: maxH };
    } catch (err) { c = null; }
    setCenter(c);
    setModalDate(r.payment_file_date);
    setModalDisp(r.date_display);
    setModalOpen(true);
    appsmith.updateModel({ activeDate: r.payment_file_date });
    appsmith.triggerEvent("onOpenBatch");
  };

  const doDownload = (r, file) => {
    if (!file) return;
    appsmith.updateModel({ dlDate: r.payment_file_date, dlType: file.type, dlName: file.name || "" });
    appsmith.triggerEvent("onDownload");
  };

  const details = model.details || [];
  const detailsReady = model.detailsFor === modalDate && !model.detailsLoading;
  const detailCols = ["Bill ID", "Due Date", "Invoice Date", "Vendor", "Billing ID", "Amount Due", "Fees", "Amount Paid", "Status"];
  const moneyCols = { "Amount Due": 1, "Fees": 1, "Amount Paid": 1 };

  const renderRow = (r, i) => {
    let files = r.files;
    if (typeof files === "string") { try { files = JSON.parse(files); } catch (e) { files = []; } }
    files = (files || []).filter((f) => f && f.type);
    const sel = picked[r.payment_file_date] || "";
    return React.createElement("tr", { key: i },
      React.createElement("td", null, r.date_display),
      React.createElement("td", null,
        React.createElement("a", { className: "qty", onClick: (e) => openBatch(r, e) }, String(r.bills_count))
      ),
      React.createElement("td", { className: "r" }, fmtMoney(r.total_amount_due)),
      React.createElement("td", { className: "dlcol" },
        React.createElement("div", { className: "dlwrap" },
          React.createElement("select", {
            className: "dl",
            value: sel,
            disabled: files.length === 0,
            onChange: (e) => { const t = e.target.value; setPicked((p) => Object.assign({}, p, { [r.payment_file_date]: t })); }
          },
            React.createElement("option", { value: "" }, files.length ? "Choose File" : "No files"),
            files.map((f, j) => React.createElement("option", { key: j, value: f.type }, f.name || f.type))
          ),
          React.createElement("button", {
            className: "dlbtn",
            disabled: !sel,
            title: "Download",
            onClick: () => { const f = files.find((x) => x.type === sel); doDownload(r, f); }
          }, React.createElement(DownloadIcon, null))
        )
      )
    );
  };

  const renderGroup = (g) =>
    React.createElement("div", { className: "month", key: g.key },
      React.createElement("div", { className: "mhead" },
        React.createElement("span", { className: "mname" }, g.label),
        React.createElement("span", { className: "mtotal" }, "Total Amount Due: " + fmtMoney(g.total))
      ),
      React.createElement("table", { className: "ptbl" },
        React.createElement("thead", null,
          React.createElement("tr", null,
            React.createElement("th", null, "Date"),
            React.createElement("th", null, "Qty of Bills"),
            React.createElement("th", { className: "r" }, "Amount Due"),
            React.createElement("th", { className: "dlcol" }, "Download Payment File")
          )
        ),
        React.createElement("tbody", null, g.rows.map(renderRow))
      )
    );

  return React.createElement("div", { className: "page" },
    (groups.length === 0 && done)
      ? React.createElement("div", { className: "empty" }, "There are no payment files for this customer.")
      : groups.map(renderGroup),
    error
      ? React.createElement("div", { className: "err" }, "Could not load more: " + error)
      : React.createElement("div", { ref: sentinelRef, className: "sentinel" }, loading ? "Loading more..." : ""),
    modalOpen && React.createElement("div", { className: "overlay", onClick: () => setModalOpen(false) },
      React.createElement("div", { className: "modal", style: center ? { position: "fixed", left: center.x + "px", top: center.y + "px", transform: "translate(-50%, -50%)", maxHeight: center.maxH + "px" } : null, onClick: (e) => e.stopPropagation() },
        React.createElement("div", { className: "mtop" },
          React.createElement("span", { className: "mtitle" }, "Bill Payment Details for " + (modalDisp || "")),
          React.createElement("span", { className: "x", onClick: () => setModalOpen(false) }, "×")
        ),
        React.createElement("div", { className: "mbody" },
          !detailsReady
            ? React.createElement("div", { className: "loading" }, "Loading...")
            : (details.length === 0
                ? React.createElement("div", { className: "loading" }, "No bills in this payment.")
                : React.createElement("div", { className: "scrollx" },
                    React.createElement("table", { className: "dtbl" },
                      React.createElement("thead", null,
                        React.createElement("tr", null, detailCols.map((c, i) =>
                          React.createElement("th", { key: i, className: moneyCols[c] ? "r" : "" }, c)))
                      ),
                      React.createElement("tbody", null,
                        details.map((d, i) =>
                          React.createElement("tr", { key: i }, detailCols.map((c, j) =>
                            React.createElement("td", { key: j, className: moneyCols[c] ? "r" : "" },
                              moneyCols[c] ? fmtMoney(d[c]) : (d[c] === null || d[c] === undefined ? "" : String(d[c])))
                          ))
                        )
                      )
                    )
                  )
              )
        ),
        React.createElement("div", { className: "mfoot" },
          React.createElement("button", { className: "okbtn", onClick: () => setModalOpen(false) }, "Ok")
        )
      )
    )
  );
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

